def G(tier, sentence, right, wrongs, expl, **kw):
    return M(tier, "Choose the correct word or phrase to fill the gap: " + sentence, right, wrongs, expl, **kw)


# ============================================================ 1. grammar
ch = p.chapter("grammar", "Grammar: verbs, concord and determiners", REF)

fig = table([["Tense", "Form", "Example"], ["present continuous", "am/is/are + -ing", "She is cooking."], ["past continuous", "was/were + -ing", "They were playing."], ["present perfect", "has/have + past participle", "He has finished."]], [110, 120, 130], rh=32, size=12)
build(ch, "tenses", "Continuous and perfect tenses", 30,
      ["Use the present and past continuous.", "Use the present perfect (have/has + past participle).", "Choose the right tense with time words."],
      [("key", "definition", "Continuous tenses", "The **present continuous** (am/is/are + -ing) shows something happening **now**: *Mama is cooking ndolé.* The **past continuous** (was/were + -ing) shows something that was **in progress** in the past: *The children were playing when it started to rain.*"),
       ("fig", fig, "Three tenses and their forms.", "A table with present continuous (is cooking), past continuous (were playing) and present perfect (has finished) and their forms."),
       ("key", "definition", "Present perfect", "The **present perfect** (have/has + past participle) links the past with now: *I have finished my homework.* *She has lived in Limbe for five years.* Words used with it: **already, yet, just, ever, never, for, since**. The past participle of regular verbs ends in -ed; irregular ones must be learnt: *eaten, gone, seen, written, bought, taken*."),
       ("key", "pieges", "Common mistakes", "- Using the continuous with state verbs: *I am knowing the answer* is wrong; say *I know*.\n- Using the present perfect with a finished time: not *I have seen him yesterday* but *I saw him yesterday*.\n- Using the wrong participle: *has went* (correct: *has gone*).\n- Forgetting the -ing form: *She is cook*.")],
      [("ex", "Example 1", "Complete: 'Look! The boys ___ football in the yard.' (play)", ["The word 'Look!' shows that it is happening now.", "Present continuous: are playing."], "are playing", None),
       ("ex", "Example 2", "Complete: 'I ___ my lunch already.' (eat)", ["The word 'already' goes with the present perfect.", "have + past participle of eat: have eaten."], "have eaten", None)],
      [G("application", "Listen! The choir ____ in the hall.", "is singing", ["sang", "has sung", "was sing"], "Listen! shows now: present continuous."),
       G("application", "She ____ the letter, so she can post it.", "has written", ["is writing yesterday", "wrote tomorrow", "has wrote"], "Present perfect: has written."),
       G("application", "When I arrived, my mother ____ in the kitchen.", "was cooking", ["is cooking", "has cooked", "cooks"], "An action in progress in the past."),
       TF("approfondissement", "'He has gone' is a correct present perfect.", True, "Has + gone (past participle of go)."),
       MA("approfondissement", "Match each verb with its past participle.", [("eat", "eaten"), ("write", "written"), ("see", "seen"), ("take", "taken")], "Irregular participles."),
       P("Read: Last Saturday, Neba was walking to the market when it began to rain. He ran under a tree. He has never seen such heavy rain.",
         [PM("Which tense is 'was walking'?", "past continuous", ["present continuous", "present perfect", "simple future"], "Was + -ing."),
          PM("Which tense is 'has never seen'?", "present perfect", ["past continuous", "simple past", "present continuous"], "Has + past participle."),
          PM("Which verb form is correct? 'Right now it ___ again.'", "is raining", ["rained", "has rain", "were raining"], "Now: present continuous.", points=2)])],
      [("'She is reading' is the...", "present continuous", ["past continuous", "present perfect", "simple past"], "Is + -ing."),
       ("Which word usually goes with the present perfect?", "already", ["yesterday", "last week", "in 2020"], "Already, yet, just, ever, never."),
       ("The past participle of 'write' is...", "written", ["wrote", "writed", "writing"], "Write - wrote - written."),
       ("'They ___ when the bell rang.'", "were playing", ["are playing", "have played", "play"], "Past continuous."),
       ("Which sentence is correct?", "I have already eaten.", ["I have already ate.", "I am already eating yesterday.", "I eaten already."], "Have + eaten.")],
      ["Only the most common uses of each tense are taught; present perfect continuous is not covered."])

fig = table([["Subject", "Verb"], ["Each of the boys", "has"], ["Neither Ako nor Bih", "was"], ["A number of pupils", "are"], ["The news", "is"], ["Maize and beans", "are"]], [200, 100], rh=28, size=13)
build(ch, "concord", "Concord: harder cases", 30,
      ["Use the right verb with each, every, either, neither and collective nouns.", "Treat uncountable nouns correctly.", "Correct longer concord mistakes."],
      [("key", "definition", "Singular words", "These words take a **singular verb**: **each, every, everyone, everybody, someone, nobody, either, neither**. *Each of the boys **has** a book. Everybody **is** here. Neither of them **was** late.* The verb agrees with *each / neither*, not with the plural word that follows."),
       ("fig", fig, "Subjects and the verbs they take.", "A table of subjects and verbs: each of the boys has; neither Ako nor Bih was; a number of pupils are; the news is; maize and beans are."),
       ("key", "retenir", "Other cases", "Two subjects joined by **and** are plural: *Maize and beans **are** cheap.* **Uncountable nouns** such as *news, advice, information, furniture, water* take a singular verb: *The news **is** good.* **A number of** takes a plural verb (*A number of pupils **are** absent*), **the number of** takes a singular verb (*The number of pupils **is** 40*)."),
       ("key", "pieges", "Common mistakes", "- *Each of the girls have*: it must be *has*.\n- *The news are*: *news* is singular.\n- *Advices* or *informations*: these words have no plural.\n- Following the word right before the verb: *The box of mangoes **is** heavy* (the subject is box).")],
      [("ex", "Example 1", "Choose: 'Each of the pupils (has / have) a pencil.'", ["The subject is Each, which is singular.", "So we use has."], "has", None),
       ("ex", "Example 2", "Correct: 'The news are good.'", ["News looks plural but is uncountable and singular.", "The news is good."], "The news is good.", None)],
      [G("application", "Everybody ____ welcome to the party.", "is", ["are", "were", "have"], "Everybody is singular."),
       G("application", "The furniture in the room ____ new.", "is", ["are", "were", "have been"], "Furniture is uncountable and singular."),
       G("application", "Rice and beans ____ my favourite meal.", "are", ["is", "was", "has"], "Two nouns joined by and: plural."),
       TF("approfondissement", "'Neither of the boys were late' is correct in careful English.", False, "Neither is singular: Neither of the boys was late."),
       MA("approfondissement", "Match each subject with its verb.", [("Each of the girls", "has"), ("The news", "is"), ("A number of goats", "are"), ("The pupils", "have")], "Check whether the subject is singular or plural."),
       P("Read: Every pupil in my class have a school bag. The information in the notice are very useful. A number of pupils is waiting outside.",
         [PM("Correct the first sentence.", "Every pupil in my class has a school bag.", ["Every pupil in my class have a school bag.", "Every pupils in my class has a school bag.", "Every pupil in my class are having a school bag."], "Every is singular."),
          PM("Correct the second sentence.", "The information in the notice is very useful.", ["The informations in the notice are very useful.", "The information in the notice are very useful.", "The informations in the notice is very useful."], "Information is uncountable."),
          PM("Correct the third sentence.", "A number of pupils are waiting outside.", ["A number of pupils is waiting outside.", "A number of pupil are waiting outside.", "A number of pupils waiting outside."], "A number of + plural verb.", points=2)])],
      [("Which verb is correct? 'Each of the girls ___ a bag.'", "has", ["have", "are", "were"], "Each is singular."),
       ("The word 'advice' is...", "uncountable", ["always plural", "a verb", "an adjective"], "Say some advice, not advices."),
       ("'Neither Ako nor Bih ___ at school.'", "was", ["were", "are", "have"], "Neither/nor with singular nouns: was."),
       ("Which sentence is correct?", "The news is good.", ["The news are good.", "The newses are good.", "The news were good."], "News is singular."),
       ("'Maize and beans ___ grown in the West Region.'", "are", ["is", "was", "has"], "Two nouns joined by and take a plural verb.")],
      [])

fig = table([["Word", "Use", "Example"], ["who", "people", "the girl who sings"], ["which", "things", "the book which I read"], ["whose", "owner", "the boy whose bag"], ["much", "uncountable", "much water"], ["many", "countable", "many books"]], [70, 110, 160], rh=28, size=13)
build(ch, "determiners-pronouns", "Pronouns and determiners: who, which, whose, some, any, much, many", 30,
      ["Use the relative pronouns who, which and whose.", "Use some, any, much, many, a few and a little correctly.", "Join two sentences with a relative pronoun."],
      [("key", "definition", "Relative pronouns", "A **relative pronoun** joins two ideas. **Who** is for people: *The girl **who** sings is my sister.* **Which** is for things and animals: *The book **which** I read was long.* **Whose** shows ownership: *The boy **whose** bag is lost is crying.*"),
       ("fig", fig, "Relative pronouns and quantity words.", "A table of words: who for people, which for things, whose for the owner, much for uncountable, many for countable, with examples."),
       ("key", "retenir", "Quantity words", "Use **many** and **a few** with **countable** nouns (*many books, a few eggs*). Use **much** and **a little** with **uncountable** nouns (*much water, a little rice*). **Some** is used in positive sentences (*I have some rice*); **any** is used in questions and negatives (*Do you have any rice? I don't have any.*)."),
       ("key", "pieges", "Common mistakes", "- *Much books* or *many water*: use **many books**, **much water**.\n- *Who* for things: *the car who* is wrong; say **which**.\n- *I don't have some money*: say **any money**.\n- Mixing *a few* (some) and *few* (not many).")],
      [("ex", "Example 1", "Join: 'I met a boy. The boy lives in Bali.' using who.", ["Both sentences are about the same boy: the second becomes a who-clause.", "I met a boy who lives in Bali."], "I met a boy who lives in Bali.", None),
       ("ex", "Example 2", "Choose much or many: 'How ___ water do you need?'", ["Water cannot be counted: it is uncountable.", "We use much."], "much", None)],
      [G("application", "The woman ____ sells fish is my aunt.", "who", ["which", "whose", "whom"], "Who is for people."),
       G("application", "I have a few friends but I don't have ____ money.", "much", ["many", "a few", "these"], "Money is uncountable."),
       G("application", "Is there ____ rice in the pot?", "any", ["some", "many", "a few"], "Any in questions."),
       TF("approfondissement", "'The tree which is behind the school is old' is correct.", True, "Which is used for things."),
       MA("approfondissement", "Match each gap with the best word.", [("The boy ___ bag is lost is crying.", "whose"), ("The book ___ I read was long.", "which"), ("How ___ eggs?", "many"), ("How ___ sugar?", "much")], "Choose by meaning."),
       P("Read the two sentences: 'I saw a man. He was selling bananas.' and 'This is the pen. I lost it yesterday.'",
         [PM("Join the first two sentences:", "I saw a man who was selling bananas.", ["I saw a man which was selling bananas.", "I saw a man whose selling bananas.", "I saw a man who he was selling bananas."], "Man is a person: who."),
          PM("Join the second two sentences:", "This is the pen which I lost yesterday.", ["This is the pen who I lost yesterday.", "This is the pen whose I lost yesterday.", "This is the pen which it I lost yesterday."], "Pen is a thing: which."),
          PM("Which is correct?", "There are a few mangoes but not much juice.", ["There are a few mangoes but not many juice.", "There is a few mangoes but not much juice.", "There are a little mangoes but not much juice."], "Few with countable, much with uncountable.", points=2)])],
      [("'I like the song ___ she sang.'", "which", ["who", "whose", "whom"], "Song is a thing."),
       ("Which noun is uncountable?", "milk", ["egg", "book", "goat"], "We say much milk."),
       ("'Do you have ___ questions?'", "any", ["some", "much", "a little"], "Any is used in questions."),
       ("'She is the girl ___ father is a doctor.'", "whose", ["who", "which", "whom's"], "Whose shows ownership."),
       ("'There aren't ___ chairs.'", "many", ["much", "a little", "some of"], "Chairs are countable.")],
      ["'Whom' is not taught at this level; check the syllabus."])

fig = table([["Degree", "Adjective", "Adverb"], ["positive", "slow", "slowly"], ["comparative", "slower", "more slowly"], ["superlative", "slowest", "most slowly"]], [110, 110, 130], rh=32, size=14)
build(ch, "comparison-adverbs", "Adjectives and adverbs: degrees of comparison", 25,
      ["Form comparatives and superlatives of adjectives and adverbs.", "Use as ... as, than and the.", "Choose between an adjective and an adverb."],
      [("key", "definition", "Degrees", "**Adjectives** have three degrees: **positive** (tall), **comparative** (taller than) and **superlative** (the tallest). Adverbs with -ly use *more / most*: *slowly - more slowly - most slowly*. Some are irregular: **good / well - better - best**, **bad / badly - worse - worst**, **far - farther - farthest**."),
       ("fig", fig, "Three degrees of an adjective and an adverb.", "A table with positive, comparative and superlative: slow, slower, slowest for the adjective and slowly, more slowly, most slowly for the adverb."),
       ("key", "retenir", "Equal and not equal", "Use **as + adjective + as** for equality: *Ako is as tall as Bih.* Use **not as ... as** for a lower degree: *Fish is not as expensive as beef.* Use **than** after a comparative: *taller than*. Use **the** with a superlative: *the tallest*."),
       ("key", "pieges", "Common mistakes", "- *Gooder, badder*: use better, worse.\n- Using an adjective instead of an adverb: *She sings good* should be *She sings well*.\n- Double comparison: *more better*.\n- *The most tallest*: use only one superlative form.")],
      [("ex", "Example 1", "Complete: 'This road is ____ than that one.' (long)", ["Two roads are compared: the comparative is needed.", "Long adds -er: longer."], "longer", None),
       ("ex", "Example 2", "Choose the right word: 'She sings (good / well).'", ["The word describes the verb sings, so we need an adverb.", "The adverb is well."], "well", None)],
      [G("application", "My bag is ____ than yours. (heavy)", "heavier", ["heavyer", "more heavy", "heaviest"], "Y becomes ier."),
       G("application", "She ran ____ of all the girls. (fast)", "the fastest", ["faster", "more fast", "the most fast"], "Superlative: the fastest."),
       G("application", "Neba speaks English ____. (good)", "well", ["good", "better good", "goodly"], "Adverb: well."),
       TF("approfondissement", "'Ako is as tall as Bih' means they have the same height.", True, "As ... as shows equality."),
       MA("approfondissement", "Match each word with its comparative form.", [("good", "better"), ("far", "farther"), ("expensive", "more expensive"), ("easy", "easier")], "Regular and irregular forms."),
       P("Read: The Wouri is long, the Benue is longer and the Sanaga is the longest of the three rivers. (Only for the grammar practice.)",
         [PM("Which word is the comparative?", "longer", ["long", "longest", "the three"], "Longer is the comparative."),
          PM("Which word is the superlative?", "longest", ["longer", "long", "rivers"], "Longest."),
          PM("Complete: 'The Wouri is not ___ long as the Benue.'", "as", ["more", "most", "than"], "Not as ... as.", points=2)])],
      [("The comparative of 'bad' is...", "worse", ["badder", "worst", "more bad"], "Bad - worse - worst."),
       ("'She dances ___ than I do.' (beautifully)", "more beautifully", ["beautifuller", "most beautifully", "beautiful"], "Long adverbs use more."),
       ("'He is ___ boy in the class.' (tall)", "the tallest", ["taller", "more tall", "tallest than"], "Superlative with the."),
       ("Which sentence is correct?", "He works hard.", ["He works hardly.", "He works hards.", "He work hardly."], "Hard is both adjective and adverb."),
       ("'A pineapple is not ___ big ___ a watermelon.'", "as ... as", ["more ... than", "so ... then", "most ... as"], "Not as ... as.")],
      ["'Farther / further' distinction is simplified."])

fig = table([["Joining word", "Shows", "Example"], ["and", "addition", "rice and beans"], ["but", "contrast", "small but strong"], ["because", "reason", "I stayed because it rained."], ["so", "result", "It rained, so I stayed."], ["although", "contrast", "Although it rained, we played."], ["if", "condition", "If it rains, we stay."]], [90, 90, 180], rh=26, size=12)
build(ch, "conjunctions-sentences", "Conjunctions, sentences and clauses", 30,
      ["Join sentences with and, but, because, so, if, although and when.", "Tell statements, questions, commands and exclamations apart.", "Tell simple, compound and complex sentences apart."],
      [("key", "definition", "Conjunctions", "A **conjunction** joins words or sentences: **and** (adds), **but** (contrast), **or** (choice), **because** (reason), **so** (result), **if** (condition), **although** (contrast), **when** (time). *I was tired **so** I slept. We stayed inside **because** it was raining.* A clause is a group of words with a subject and a verb."),
       ("fig", fig, "Conjunctions and what they show.", "A table of joining words: and for addition, but for contrast, because for reason, so for result, although for contrast and if for condition, each with an example sentence."),
       ("key", "retenir", "Kinds of sentences", "A **statement** gives information. A **question** asks. A **command** tells someone to do something. An **exclamation** shows strong feeling (*What a big fish!*). A **simple** sentence has one clause; a **compound** sentence joins two clauses with *and, but, or, so*; a **complex** sentence has a main clause and a clause with *because, although, if, when*."),
       ("key", "pieges", "Common mistakes", "- Using **but** and **although** together: *Although it rained, but we played* is wrong.\n- Using *because* and *so* together in the same sentence.\n- Starting a sentence with *because* and not finishing it (a sentence needs a main clause).\n- Forgetting the comma after a clause that starts with *although* or *if*.")],
      [("ex", "Example 1", "Join with 'because': 'Ako was late. The bus broke down.'", ["The second sentence is the reason for the first.", "Ako was late because the bus broke down."], "Ako was late because the bus broke down.", None),
       ("ex", "Example 2", "What kind of sentence is: 'Close the door, please.'?", ["It tells someone to do something.", "It is a command."], "A command.", None)],
      [G("application", "It was raining, ____ we stayed inside.", "so", ["because", "but", "although"], "So shows the result."),
       G("application", "____ it was hot, the children played football.", "Although", ["Because", "So", "And"], "Although shows contrast."),
       G("application", "I will go to the market ____ it does not rain.", "if", ["but", "so", "because"], "If shows a condition."),
       TF("approfondissement", "'What a beautiful day!' is an exclamation.", True, "It shows strong feeling."),
       MA("approfondissement", "Match each sentence with its kind.", [("Where is my pen?", "question"), ("Sit down.", "command"), ("The sun is hot.", "statement"), ("How kind you are!", "exclamation")], "Look at the meaning."),
       P("Read: Ngum wanted to play football. It was raining heavily. He stayed at home and he read a book.",
         [PM("Join the first two sentences with 'but':", "Ngum wanted to play football, but it was raining heavily.", ["Ngum wanted to play football, because it was raining heavily.", "Ngum wanted to play football, so it was raining heavily.", "Ngum wanted to play football, if it was raining heavily."], "But shows the contrast."),
          PM("Which word shows the reason? 'He stayed at home because it was raining.'", "because", ["He", "stayed", "home"], "Because gives the reason."),
          PM("'Ngum read a book and he stayed at home' is a...", "compound sentence", ["simple sentence", "question", "command"], "Two clauses joined by and.", points=2)])],
      [("'I was hungry ___ I ate some fufu.'", "so", ["although", "if", "because"], "A result."),
       ("'He is poor ___ he is happy.'", "but", ["so", "because", "if"], "Contrast."),
       ("Which sentence is a command?", "Open your books.", ["How cold it is!", "Are you ready?", "She is reading."], "It tells someone to do something."),
       ("A conjunction is a...", "joining word", ["naming word", "doing word", "describing word"], "And, but, because."),
       ("Which sentence is complex?", "I stayed home because I was ill.", ["I stayed home.", "I stayed home and rested.", "Stay home."], "It has a main clause and a because-clause.")],
      [])

fig = boxes(["Direct: Ako said, \"I am tired.\"", "Indirect: Ako said that he was tired.", "I becomes he; am becomes was", "Quotation marks disappear"], size=13)
build(ch, "reported-speech", "Direct and indirect (reported) speech", 30,
      ["Write direct speech with quotation marks.", "Change simple statements and questions to reported speech.", "Change pronouns and tenses correctly."],
      [("key", "definition", "Direct and indirect speech", "**Direct speech** gives the exact words of the speaker inside **quotation marks**: *Ako said, \"I am tired.\"* **Indirect (reported) speech** tells what was said without the exact words: *Ako said that he was tired.* There are no quotation marks, and the pronouns and tenses change."),
       ("fig", fig, "From direct to indirect speech.", "Four boxes: direct speech Ako said I am tired; indirect speech Ako said that he was tired; I becomes he and am becomes was; quotation marks disappear."),
       ("key", "methode", "How to change", "1. Remove the quotation marks and add **that**.\n2. Change the **pronouns** (I - he/she, my - his/her, we - they).\n3. Move the **tense one step back**: *am/is - was*, *are - were*, *play - played*, *will - would*, *can - could*.\n4. Change the **time and place words** if needed: *today - that day, tomorrow - the next day, here - there*."),
       ("key", "retenir", "Questions and commands", "A reported **question** keeps no question mark and the word order of a statement: *She asked, \"Where do you live?\"* becomes *She asked where I lived.* A reported **command** uses *to*: *The teacher said, \"Sit down.\"* becomes *The teacher told us to sit down.*"),
       ("key", "pieges", "Common mistakes", "- Keeping the pronoun *I* in the reported sentence.\n- Keeping the question mark or quotation marks.\n- Not moving the tense back: *Ako said that he is tired*.\n- Using *if* wrongly: for a yes/no question use *if* or *whether*.")],
      [("ex", "Example 1", "Change to reported speech: Mary said, \"I like mangoes.\"", ["Remove the quotation marks, add that, change I to she and like to liked.", "Mary said that she liked mangoes."], "Mary said that she liked mangoes.", None),
       ("ex", "Example 2", "Change to direct speech: The teacher said that the test would start at nine.", ["Use the exact words of the teacher: will instead of would, and quotation marks.", "The teacher said, \"The test will start at nine.\""], "The teacher said, \"The test will start at nine.\"", None)],
      [M("application", "Which sentence is in direct speech?", "Neba said, \"I am hungry.\"", ["Neba said that he was hungry.", "Neba told us he was hungry.", "Neba said he was hungry."], "It uses the exact words with quotation marks."),
       M("application", "Change to reported speech: She said, \"I am happy.\"", "She said that she was happy.", ["She said that I am happy.", "She said that she is happy.", "She said, that she was happy."], "Pronoun and tense change."),
       M("application", "Which word is added in reported statements?", "that", ["which", "who", "because"], "She said that ..."),
       TF("approfondissement", "In reported speech we keep the quotation marks.", False, "Quotation marks are removed."),
       MA("approfondissement", "Match the direct form with the reported form.", [("\"I am ill.\"", "He said that he was ill."), ("\"We can swim.\"", "They said that they could swim."), ("\"I will come.\"", "She said that she would come."), ("\"Where do you live?\"", "He asked where I lived.")], "Shift the tense and the pronouns."),
       P("The headmaster said, \"The school will close at noon tomorrow. All pupils must bring their books.\"",
         [PM("Which is the correct reported form of the first sentence?", "The headmaster said that the school would close at noon the next day.", ["The headmaster said that the school will close at noon tomorrow.", "The headmaster said the school closes at noon tomorrow.", "The headmaster said, the school would close at noon the next day."], "Will - would, tomorrow - the next day."),
          PM("Which word replaces 'will' in reported speech?", "would", ["could", "shall", "did"], "Will - would."),
          PM("Which is a good opening for the reported second sentence?", "He added that all pupils had to bring their books.", ["He added that all pupils must bring our books.", "He added, all pupils had to bring their books.", "He added, \"all pupils had to bring their books\"."], "Remove quotation marks and shift the tense.", points=2)])],
      [("'She said that she was tired' is...", "reported speech", ["direct speech", "a command", "a question"], "No quotation marks; tense shifted."),
       ("Reported form of 'I will help you': He said that he ___ help me.", "would", ["will", "can", "did"], "Will - would."),
       ("Direct speech is written in...", "quotation marks", ["brackets", "capitals only", "italics only"], "\"...\""),
       ("'Today' often becomes ___ in reported speech.", "that day", ["tomorrow", "now", "last year"], "Time words change."),
       ("'He asked, \"Where is the market?\"' - reported form:", "He asked where the market was.", ["He asked where is the market?", "He asked that where the market is.", "He asked, where was the market."], "A reported question uses statement order.")],
      ["Back-shifting rules are given in their simplest form; exceptions (general truths) are not covered."])

fig = boxes(["Active: The farmer plants the maize.", "Passive: The maize is planted by the farmer.", "Form: is/are/was/were + past participle", "Use the passive when the doer is not important"], size=13)
build(ch, "passive-voice", "Active and passive voice (introduction)", 25,
      ["Tell an active sentence from a passive sentence.", "Change simple active sentences into the passive.", "Choose the right form of 'to be' and the past participle."],
      [("key", "definition", "Active and passive", "In an **active** sentence the doer comes first: *The farmer **plants** the maize.* In a **passive** sentence the thing receiving the action comes first: *The maize **is planted** by the farmer.* The passive is formed with **am / is / are / was / were + past participle**."),
       ("fig", fig, "Active and passive.", "Four boxes: active, the farmer plants the maize; passive, the maize is planted by the farmer; the form is a part of to be plus the past participle; the passive is used when the doer is not important."),
       ("key", "methode", "Changing to the passive", "1. Find the **object** of the active sentence (*the maize*): it becomes the new subject.\n2. Use the correct form of **to be** in the same tense (*plants - is planted*; *planted - was planted*).\n3. Add the **past participle**.\n4. Add **by + the doer** if it is useful (*by the farmer*)."),
       ("key", "pieges", "Common mistakes", "- Using the simple past participle wrongly: *was wrote* (correct: *was written*).\n- Forgetting the verb *to be*: *The maize planted by the farmer*.\n- Keeping the wrong tense: *The letter is written yesterday* (should be *was written*).\n- Using the passive when the active is clearer.")],
      [("ex", "Example 1", "Change to the passive: 'The girl sweeps the classroom.'", ["Object: the classroom (new subject). Tense: present simple, so is + participle.", "The classroom is swept by the girl."], "The classroom is swept by the girl.", None),
       ("ex", "Example 2", "Change to the passive: 'Mama cooked the ndolé.'", ["Object: the ndolé. Tense: past simple, so was + participle.", "The ndolé was cooked by Mama."], "The ndolé was cooked by Mama.", None)],
      [M("application", "Which sentence is passive?", "The letter was written by Ada.", ["Ada wrote the letter.", "Ada is writing.", "Ada writes letters."], "Was + past participle."),
       G("application", "The windows ____ by the boys yesterday.", "were cleaned", ["are cleaning", "cleaned", "was clean"], "Plural, past: were cleaned."),
       G("application", "English ____ in many schools in Cameroon.", "is taught", ["teaches", "was teach", "is teach"], "Present passive."),
       TF("approfondissement", "'The cake was eaten by the children' is passive.", True, "Was + past participle."),
       MA("approfondissement", "Match each active sentence with its passive.", [("Ako broke the cup.", "The cup was broken by Ako."), ("Bih sings the song.", "The song is sung by Bih."), ("The farmers grow cocoa.", "Cocoa is grown by the farmers."), ("Che wrote the story.", "The story was written by Che.")], "Keep the tense."),
       P("Read: Mr Eko built this house in 2010. The workers painted it last month. People visit it every year. (Only for grammar practice.)",
         [PM("Which is the passive of 'Mr Eko built this house'?", "This house was built by Mr Eko.", ["This house is built by Mr Eko.", "This house built Mr Eko.", "This house was build by Mr Eko."], "Past: was built."),
          PM("Which is the passive of 'The workers painted it last month'?", "It was painted by the workers last month.", ["It is painted by the workers last month.", "It was paint by the workers.", "It painted the workers."], "Past passive."),
          PM("Which is the passive of 'People visit it every year'?", "It is visited every year.", ["It was visited every year.", "It visits every year.", "It is visit every year."], "Present passive.", points=2)])],
      [("The passive is formed with...", "to be + past participle", ["will + infinitive", "-ing only", "have + noun"], "For example is planted."),
       ("Which is correct?", "The book was written by Ada.", ["The book was wrote by Ada.", "The book is written yesterday.", "The book writing by Ada."], "Was written."),
       ("The passive of 'Dogs chase cats' is...", "Cats are chased by dogs.", ["Cats chase dogs.", "Cats was chased by dogs.", "Dogs are chased by cats."], "Present: are chased."),
       ("In an active sentence the doer is...", "the subject", ["the object", "the verb", "the title"], "The farmer plants..."),
       ("Which sentence is active?", "Mama cooked the rice.", ["The rice was cooked by Mama.", "The rice is cooked.", "The rice was cooked."], "The doer comes first.")],
      ["Passive voice may belong to later classes; included as an introduction only (flag for the teacher to keep or drop)."])

