build(ch, "word-building", "Word building: prefixes and suffixes", 25,
      ["Make new words with prefixes and suffixes.", "Spell words when a suffix is added.", "Use word families."],
      [("key", "definition", "Prefixes and suffixes", "A **prefix** is added to the **front** of a word and changes its meaning: **un-** (not): *unhappy*; **re-** (again): *rewrite*; **dis-** (not): *disagree*. A **suffix** is added to the **end**: **-ful** (full of): *helpful*; **-less** (without): *careless*; **-ness** (state): *kindness*; **-ly** makes adverbs: *slowly*."),
       ("fig", fig, "Common prefixes and suffixes.", "A table of prefixes and suffixes: un means not, re means again, dis means not, ful means full of, less means without, ness means state, each with an example."),
       ("key", "retenir", "Spelling changes", "If a word ends in a **silent e**, drop it before a suffix that starts with a vowel: *hope - hoping*, but keep it before *-ful* and *-ness*: *hopeful*. If a word ends in **consonant + y**, change **y to i**: *happy - happiness, easy - easily*. Double the last letter in short words: *run - running, big - bigger*."),
       ("key", "pieges", "Common mistakes", "- *Unnecessary* is spelt with *nn* (un + necessary): do not drop a letter.\n- *Carefull* or *usefull*: the suffix is **-ful** with one l.\n- Adding a prefix and changing the spelling of the base word.\n- Confusing *-less* (without) and *-ful* (with).")],
      [("ex", "Example 1", "Make a word meaning 'without hope' using a suffix.", ["The suffix that means without is -less.", "hope + less = hopeless."], "hopeless", None),
       ("ex", "Example 2", "Add -ness to 'happy'.", ["The word ends in consonant + y: change y to i.", "happi + ness = happiness."], "happiness", None)],
      [M("application", "What does 'unhappy' mean?", "not happy", ["very happy", "happy again", "without happiness"], "Un- means not."),
       M("application", "Which word means 'without care'?", "careless", ["careful", "recare", "uncare"], "-less means without."),
       M("application", "Which word means 'write again'?", "rewrite", ["unwrite", "writeful", "miswrite"], "Re- means again."),
       TF("approfondissement", "The prefix 'dis-' can mean 'not' (disagree).", True, "Dis- gives the opposite."),
       MA("approfondissement", "Match each word with its meaning.", [("helpful", "giving help"), ("homeless", "without a home"), ("unkind", "not kind"), ("rebuild", "build again")], "Prefix or suffix gives the meaning."),
       P("Read: The farmer was hopeful when the rain began. He was thankful for the water. His crops grew, and the harvest was plentiful.",
         [PM("Which suffix is in 'hopeful'?", "-ful", ["-less", "-ness", "-ly"], "Full of hope."),
          PM("What would 'hopeless' mean?", "without hope", ["full of hope", "hope again", "not hope"], "-less = without."),
          PM("Which word is formed with a prefix?", "unhappy", ["happily", "kindness", "helpful"], "Un- is a prefix.", points=2)])],
      [("'Re-' means...", "again", ["not", "without", "full of"], "Rebuild, rewrite."),
       ("'Kind' + '-ness' =", "kindness", ["kindy", "kindful", "kindless"], "The suffix -ness forms a noun."),
       ("'Harmless' means...", "without harm", ["full of harm", "harm again", "not harm"], "-less means without."),
       ("The opposite of 'honest' using a prefix is...", "dishonest", ["unhonest", "rehonest", "honestless"], "Dis- + honest."),
       ("'Happy' becomes 'happiness' by changing...", "y to i", ["i to y", "e to a", "s to z"], "Y changes to i before -ness.")],
      [])

