       TF("approfondissement", "'A stitch in time saves nine' advises us to act early.", True, "A small repair now stops a big problem later."),
       MA("approfondissement", "Match each saying with its meaning.", [("Two heads are better than one", "we solve problems better together"), ("Many hands make light work", "sharing makes work easy"), ("Practice makes perfect", "doing things again makes us better"), ("Honesty is the best policy", "telling the truth is wise")], "Think about the lesson."),
