build(ch, "formal-letter", "Writing a formal letter", 35,
      ["Know the layout of a formal letter.", "Choose the right greeting and closing.", "Write a short polite formal letter."],
      [("key", "definition", "Layout", "A formal letter has: the **writer's address** and the **date** (top right); the **receiver's title and address** (left); the **greeting** (*Dear Sir,* / *Dear Madam,*); a **subject heading** (*REQUEST FOR PERMISSION*); the **body** in short paragraphs; the **closing** (*Yours faithfully,*) and the **name** of the writer."),
       ("fig", fig, "Layout of a formal letter.", "A letter with the writer's address and date at the top right, the headmaster's name on the left, Dear Sir, a heading REQUEST FOR PERMISSION, a short body, Yours faithfully and the name Ako Ndip."),
       ("key", "methode", "Writing the body", "Paragraph 1: **why you write** (*I am writing to ask for permission to ...*). Paragraph 2: the **reason and details**. Paragraph 3: **thanks and hope** (*I hope you will agree. Thank you for your help.*). Use a **polite, formal** tone: no short forms (*do not*, not *don't*), no slang. Use **Yours faithfully** with *Dear Sir/Madam* and **Yours sincerely** with a name."),
       ("key", "pieges", "Common mistakes", "- Using a friendly style: *Hi!* or *Love*.\n- Forgetting the subject heading or the date.\n- Using *Yours faithfully* with a named person (use *Yours sincerely*).\n- Using short forms and slang.")],
      [("ex", "Example 1", "Which closing goes with 'Dear Sir'?", ["We do not know the name of the receiver, so we use the formal closing.", "Yours faithfully."], "Yours faithfully,", None),
       ("ex", "Example 2", "Write a heading for a letter to the headmaster asking for permission to leave school early.", ["The heading is short and in capital letters.", "REQUEST FOR PERMISSION TO LEAVE SCHOOL EARLY"], "REQUEST FOR PERMISSION TO LEAVE SCHOOL EARLY", None)],
      [M("application", "Which greeting is formal?", "Dear Madam,", ["Hi Aunty,", "Hello friend,", "My dear sweet,"], "Formal letters use Dear Sir/Madam."),
       M("application", "Which closing is for 'Dear Mr Ako'?", "Yours sincerely,", ["Yours faithfully,", "Love,", "Bye,"], "Use sincerely when we know the name."),
       M("application", "A formal letter is written in a...", "polite style", ["slang style", "joking style", "secret code"], "It is polite and clear."),
       TF("approfondissement", "A formal letter has a subject heading.", True, "It tells the purpose."),
       MA("approfondissement", "Match each part of a formal letter with an example.", [("greeting", "Dear Sir,"), ("heading", "REQUEST FOR PERMISSION"), ("closing", "Yours faithfully,"), ("date", "5 March 2026")], "Learn the parts."),
       O("Write a formal letter (about 70 words) to your headmaster asking for permission to attend a family event on Friday. Give your address and the date.",
         "12 School Road, Buea\n5 March 2026\n\nThe Headmaster\nGovernment Primary School, Buea\n\nDear Sir,\n\nREQUEST FOR PERMISSION\n\nI am writing to ask for permission to be absent from school on Friday, 8 March. My cousin's wedding will take place in Bamenda and my parents wish me to attend. I will bring a note from my father. I will copy all the lessons that I miss. Thank you for your kind help.\n\nYours faithfully,\nAko Ndip",
         "Marks (8): addresses and date (2); greeting and closing correct (1); heading (1); reason and polite tone (2); organisation in paragraphs (1); spelling and punctuation (1).", tier="examen", points=8, difficulty=3)],
      [("A formal letter to the headmaster starts with...", "Dear Sir/Madam,", ["Hi,", "Hello pal,", "Dear friend,"], "A formal greeting."),
       ("'Yours faithfully' is used when...", "we do not know the name", ["we know the person well", "we write to a friend", "we write a story"], "With Dear Sir/Madam."),
       ("The subject heading of a letter is...", "a short title of the purpose", ["the closing", "the writer's name", "a joke"], "REQUEST FOR PERMISSION."),
       ("In a formal letter we avoid...", "slang and short forms", ["the date", "paragraphs", "thanks"], "Be polite and clear."),
       ("Where does the writer's address go?", "top right", ["bottom left", "after the closing", "nowhere"], "At the top right.")],
      ["Layout conventions vary slightly between textbooks; the model letter is original; check the school's preferred layout."])

