build(ch, "composition", "Composition: narrative and descriptive writing", 40,
      ["Plan a narrative composition.", "Write a descriptive composition using the senses and good adjectives.", "Check your work: spelling, punctuation and tense."],
      [("key", "methode", "Narrative composition", "Plan before you write: **introduction** (who, where, when), **build-up** (events, the problem), **ending** (solution and lesson). Write in the **past tense**, in **paragraphs**. Use **time words** (*one morning, soon, suddenly, at last*), **direct speech** and strong verbs. Give a **title**. Length: about 150 words at this level."),
       ("fig", fig, "The plan of a narrative composition.", "Three boxes: introduction with who, where and when; build-up with events and the problem; ending with the solution and the lesson."),
       ("key", "methode", "Descriptive composition", "To describe a person, an animal, a place or an event, plan what to say about each part: **appearance, sounds, smells, feelings**. Use adjectives, comparisons (*as fast as a motorbike*) and adverbs. Keep a clear order, for example from the entrance to the end of a market."),
       ("key", "pieges", "Common mistakes", "- No plan, so the story has no clear parts.\n- Changing tense or person in the middle.\n- A long list of events with no problem and no ending.\n- Not checking spelling and punctuation at the end.")],
      [("ex", "Example 1", "Write an opening paragraph for a story called 'The Storm'.", ["Say when, where and who, and prepare the problem.", "One hot afternoon, Neba was playing football in the yard in Limbe when the sky suddenly turned black."], "One hot afternoon, Neba was playing football in the yard in Limbe when the sky suddenly turned black.", None),
       ("ex", "Example 2", "Write two descriptive sentences about a market using the senses.", ["See and hear: colours and noises.", "The market is full of colourful cloths and loud voices. It smells of fresh fish and roasted corn."], "The market is full of colourful cloths and loud voices. It smells of fresh fish and roasted corn.", None)],
      [M("application", "Which part of a composition presents the characters and the place?", "introduction", ["ending", "heading", "closing"], "Who, where, when."),
       M("application", "In which tense is a narrative usually written?", "the past tense", ["the future tense", "the present tense only", "no tense"], "We tell what happened."),
       M("application", "Which is a good time word for a story?", "suddenly", ["green", "table", "under"], "It starts an event."),
       TF("approfondissement", "A good composition is divided into paragraphs.", True, "Each paragraph has one idea."),
       MA("approfondissement", "Match each sense with a good description.", [("see", "bright red tomatoes"), ("hear", "the noise of motorbikes"), ("smell", "the smell of roasted fish"), ("touch", "the rough skin of a pineapple")], "Use the senses."),
       O("Write a composition of about 120 words called 'A Day I Will Never Forget'. Use a plan: introduction, build-up and ending.",
         "Last year, on my birthday, my family and I travelled from Bamenda to Limbe to see the sea. We left at six o'clock. Along the way we saw green hills and tea plantations. At the beach I ran toward the waves but I suddenly fell on the wet sand and everyone laughed. Then my father helped me up and we built a big sand castle together. At the end of the day, we ate grilled fish and plantain by the sea. I was tired but very happy. It was the best day of my life.",
         "Marks (10): introduction (1); build-up with events (2); ending (1); past tense kept (1); paragraphs (1); varied vocabulary and sentences (2); spelling and punctuation (2).", tier="examen", points=10, difficulty=3)],
      [("A narrative composition tells...", "a story", ["a list of prices", "a map", "a poem only"], "Events in order."),
       ("A composition plan has...", "introduction, build-up and ending", ["only an ending", "only a title", "only adjectives"], "Three parts."),
       ("Which sentence starts a story well?", "One morning, Ada went to the river.", ["The end.", "Therefore.", "Because of rice."], "A time and place."),
       ("A descriptive composition uses...", "the senses and adjectives", ["only numbers", "only dates", "only rules"], "It shows how things look, sound and smell."),
       ("At the end we should always...", "check spelling and punctuation", ["start again", "copy the question", "write a new title"], "Revise your work.")],
      ["Word lengths are indicative; the model composition is original."])

# ============================================================ 5. poem and oral
ch = p.chapter("oral-poetry", "Poems and oral English", REF)

fig = table([["Device", "Meaning", "Example"], ["simile", "compare with like or as", "as busy as a bee"], ["metaphor", "say one thing is another", "The sun is a golden coin."], ["personification", "give a thing human actions", "The wind whispered."]], [100, 130, 130], rh=36, size=12)
